package com.example.appointment.appointment;
import com.example.appointment.common.DomainException; import com.example.appointment.offering.*; import com.example.appointment.queue.*; import com.example.appointment.staff.*; import com.example.appointment.user.User; import java.time.*; import java.util.*; import javax.validation.Valid; import javax.validation.constraints.*; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController public class AppointmentController { private final AppointmentService service; private final ServiceOfferingRepository offerings; private final StaffProfileRepository staff; private final AvailabilityRepository availability; private final AppointmentRepository appointments; private final QueueEntryRepository queues; public AppointmentController(AppointmentService s,ServiceOfferingRepository o,StaffProfileRepository st,AvailabilityRepository av,AppointmentRepository a,QueueEntryRepository q){service=s;offerings=o;staff=st;availability=av;appointments=a;queues=q;} @GetMapping("/api/slots") List<Slot> slots(@RequestParam Long serviceId,@RequestParam LocalDate date,@RequestParam(required=false)Long staffId){ServiceOffering offering=offerings.findById(serviceId).filter(ServiceOffering::isActive).orElseThrow(()->DomainException.notFound("Active service not found"));List<StaffProfile> members=staffId==null?staff.activeForService(serviceId):Collections.singletonList(staff.findById(staffId).orElseThrow(()->DomainException.notFound("Staff not found")));List<Slot>x=new ArrayList<>();for(StaffProfile member:members){if(!member.isActive()||member.getServices().stream().noneMatch(s->s.getId().equals(serviceId)))continue;for(Availability a:availability.findByStaffIdAndDateOrderByStartTime(member.getId(),date)){for(LocalTime start=a.getStartTime();!start.plusMinutes(offering.getDurationMinutes()).isAfter(a.getEndTime());start=start.plusMinutes(offering.getDurationMinutes())){LocalTime end=start.plusMinutes(offering.getDurationMinutes());if(LocalDateTime.of(date,start).isAfter(LocalDateTime.now())&&appointments.overlaps(member.getId(),date,start,end).isEmpty())x.add(new Slot(member.getId(),date,start,end,OfferingController.out(offering)));}}}x.sort(Comparator.comparing((Slot s)->s.startTime).thenComparing(s->s.staffId));return x;} @PostMapping("/api/appointments") @ResponseStatus(HttpStatus.CREATED) AppointmentResponse book(@Valid @RequestBody Booking r,Authentication a){return out(service.book(user(a),r.serviceId,r.staffId,r.appointmentDate,r.startTime));} @GetMapping("/api/appointments") Page<AppointmentResponse> list(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(user(a),PageRequest.of(page,Math.min(size,100),Sort.by("appointmentDate","startTime"))).map(this::out);} @GetMapping("/api/appointments/history") Page<AppointmentResponse> history(Authentication a,@RequestParam(defaultValue="0")int page){return service.list(user(a),PageRequest.of(page,20,Sort.by(Sort.Direction.DESC,"appointmentDate"))).map(this::out);} @GetMapping("/api/appointments/{id}") AppointmentResponse get(@PathVariable Long id,Authentication a){return out(service.authorized(id,user(a),true));} @PatchMapping("/api/appointments/{id}/cancel") AppointmentResponse cancel(@PathVariable Long id,Authentication a){return out(service.cancel(id,user(a)));} @PatchMapping("/api/appointments/{id}/reschedule") AppointmentResponse reschedule(@PathVariable Long id,@Valid @RequestBody Reschedule r,Authentication a){return out(service.reschedule(id,user(a),r.staffId,r.appointmentDate,r.startTime));} @PostMapping("/api/appointments/{id}/check-in") QueueResponse checkIn(@PathVariable Long id,Authentication a){return queue(service.checkIn(id,user(a)));} @GetMapping("/api/appointments/{id}/queue-status") QueueResponse queueStatus(@PathVariable Long id,Authentication a){service.authorized(id,user(a),true);return queue(queues.findByAppointmentId(id).orElseThrow(()->DomainException.notFound("Queue entry not found")));} @PatchMapping("/api/appointments/{id}/complete") AppointmentResponse complete(@PathVariable Long id,Authentication a){return out(service.complete(id,user(a)));} private User user(Authentication a){return (User)a.getPrincipal();} private AppointmentResponse out(Appointment a){return new AppointmentResponse(a.getId(),a.getConfirmationNumber(),a.getStaff().getId(),a.getService().getId(),a.getAppointmentDate(),a.getStartTime(),a.getEndTime(),a.getStatus(),a.getTokenNumber());} static QueueResponse queue(QueueEntry q){return new QueueResponse(q.getAppointment().getId(),q.getTokenNumber(),q.getQueuePosition(),q.getEstimatedWaitingTimeMinutes(),q.getStatus().name(),q.getUpdatedAt());} public static class Booking{@NotNull public Long serviceId,staffId;@NotNull public LocalDate appointmentDate;@NotNull public LocalTime startTime;} public static class Reschedule{@NotNull public Long staffId;@NotNull public LocalDate appointmentDate;@NotNull public LocalTime startTime;} public static class Slot{public final Long staffId;public final LocalDate date;public final LocalTime startTime,endTime;public final OfferingController.ServiceOfferingResponse service;Slot(Long s,LocalDate d,LocalTime a,LocalTime b,OfferingController.ServiceOfferingResponse o){staffId=s;date=d;startTime=a;endTime=b;service=o;}} public static class AppointmentResponse{public final Long id;public final String confirmationNumber;public final Long staffId,serviceId;public final LocalDate appointmentDate;public final LocalTime startTime,endTime;public final AppointmentStatus status;public final String tokenNumber;AppointmentResponse(Long i,String c,Long st,Long se,LocalDate d,LocalTime a,LocalTime e,AppointmentStatus x,String t){id=i;confirmationNumber=c;staffId=st;serviceId=se;appointmentDate=d;startTime=a;endTime=e;status=x;tokenNumber=t;}} public static class QueueResponse{public final Long appointmentId;public final String tokenNumber;public final int queuePosition,estimatedWaitingTimeMinutes;public final String status;public final java.time.Instant lastUpdatedAt;QueueResponse(Long a,String t,int p,int w,String s,java.time.Instant u){appointmentId=a;tokenNumber=t;queuePosition=p;estimatedWaitingTimeMinutes=w;status=s;lastUpdatedAt=u;}} }
